using Npgsql;
var b=WebApplication.CreateBuilder(args);
var cs=Environment.GetEnvironmentVariable("DATABASE_URL")??"Host=db;Port=5432;Database=admission;Username=admission;Password=admission";
var duration=int.TryParse(Environment.GetEnvironmentVariable("HOLD_DURATION_SECONDS"),out var d)&&d>0?d:600;
b.Services.AddSingleton(new NpgsqlDataSourceBuilder(cs).Build());b.Services.AddHostedService<ExpiryWorker>();b.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));
var app=b.Build();app.UseCors();app.Use(async(c,n)=>{try{await n();}catch(NpgsqlException){c.Response.StatusCode=503;await c.Response.WriteAsJsonAsync(new{message="The request could not be completed. Check your details and try again."});}catch{c.Response.StatusCode=500;await c.Response.WriteAsJsonAsync(new{message="The request could not be completed. Check your details and try again."});}});var db=app.Services.GetRequiredService<NpgsqlDataSource>();await Init(db);
app.MapGet("/health",()=>Results.Ok(new{status="healthy"}));
app.MapPost("/classes",async(CreateClass x)=>{if(string.IsNullOrWhiteSpace(x.Name)||x.Name.Trim().Length>120||x.TotalSeats is <1 or >100000)return (IResult)Results.BadRequest(new{message="The request could not be completed. Check your details and try again."});await using var c=db.CreateCommand("INSERT INTO classes(id,name,total_seats) VALUES(@id,@n,@s) RETURNING id,name,total_seats");var id="c_"+Guid.NewGuid().ToString("N");c.Parameters.AddWithValue("id",id);c.Parameters.AddWithValue("n",x.Name.Trim());c.Parameters.AddWithValue("s",x.TotalSeats);await using var r=await c.ExecuteReaderAsync();await r.ReadAsync();return (IResult)Results.Created("/classes/"+id,new{id=r.GetString(0),name=r.GetString(1),totalSeats=r.GetInt32(2)});});
app.MapGet("/classes",async()=>Results.Ok(await Classes(db,null)));
app.MapGet("/classes/{id}",async(string id)=>{var a=await Classes(db,id);if(a.Count==0)return (IResult)Results.NotFound(new{message="The requested class was not found."});return (IResult)Results.Ok(a[0]);});
app.MapPost("/classes/{id}/holds",async(string id,HttpRequest req)=>{var s=Student(req);if(s is null)return (IResult)Results.BadRequest(new{message="The request could not be completed. Check your details and try again."});await using var c=await db.OpenConnectionAsync();await using var t=await c.BeginTransactionAsync();await using var cl=new NpgsqlCommand("SELECT total_seats FROM classes WHERE id=@id FOR UPDATE",c,t);cl.Parameters.AddWithValue("id",id);var seats=await cl.ExecuteScalarAsync();if(seats is null)return (IResult)Results.NotFound(new{message="The request could not be completed. Check your details and try again."});await using(var e=new NpgsqlCommand("UPDATE holds SET status='EXPIRED' WHERE class_id=@c AND status='HELD' AND expires_at<=now()",c,t)){e.Parameters.AddWithValue("c",id);await e.ExecuteNonQueryAsync();}await using(var a=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM holds WHERE class_id=@c AND student_id=@s AND status IN('HELD','CONFIRMED'))",c,t)){a.Parameters.AddWithValue("c",id);a.Parameters.AddWithValue("s",s);if((bool)(await a.ExecuteScalarAsync())!)return (IResult)Results.Conflict(new{message="The request could not be completed. Check your details and try again."});}await using(var n=new NpgsqlCommand("SELECT count(*) FROM holds WHERE class_id=@c AND (status='CONFIRMED' OR(status='HELD' AND expires_at>now()))",c,t)){n.Parameters.AddWithValue("c",id);if((long)(await n.ExecuteScalarAsync())!>=(int)seats)return (IResult)Results.Conflict(new{message="The request could not be completed. Check your details and try again."});}var h="h_"+Guid.NewGuid().ToString("N");await using var i=new NpgsqlCommand("INSERT INTO holds(id,class_id,student_id,status,expires_at) VALUES(@h,@c,@s,'HELD',now()+(@d*interval '1 second')) RETURNING expires_at",c,t);i.Parameters.AddWithValue("h",h);i.Parameters.AddWithValue("c",id);i.Parameters.AddWithValue("s",s);i.Parameters.AddWithValue("d",duration);var expiry=(DateTime)(await i.ExecuteScalarAsync())!;await t.CommitAsync();return (IResult)Results.Created("/holds/"+h,new{holdId=h,classId=id,studentId=s,status="HELD",expiresAt=DateTime.SpecifyKind(expiry,DateTimeKind.Utc)});});
app.MapGet("/holds/{id}",async(string id)=>{await using var c=db.CreateCommand("SELECT id,class_id,status,expires_at FROM holds WHERE id=@id");c.Parameters.AddWithValue("id",id);await using var r=await c.ExecuteReaderAsync();if(!await r.ReadAsync())return (IResult)Results.NotFound(new{message="The request could not be completed. Check your details and try again."});var s=r.GetString(2);var e=r.GetDateTime(3);if(s=="HELD"&&e<=DateTime.UtcNow)s="EXPIRED";return (IResult)Results.Ok(new{holdId=r.GetString(0),classId=r.GetString(1),status=s,expiresAt=DateTime.SpecifyKind(e,DateTimeKind.Utc)});});
app.MapPost("/holds/{id}/confirm",async(string id,HttpRequest req)=>{var s=Student(req);if(s is null)return (IResult)Results.BadRequest(new{message="The request could not be completed. Check your details and try again."});await using var c=await db.OpenConnectionAsync();await using var t=await c.BeginTransactionAsync();await using var lookup=new NpgsqlCommand("SELECT class_id FROM holds WHERE id=@id",c,t);lookup.Parameters.AddWithValue("id",id);var cl=(string?)await lookup.ExecuteScalarAsync();if(cl is null)return (IResult)Results.NotFound(new{message="The request could not be completed. Check your details and try again."});await using(var classLock=new NpgsqlCommand("SELECT id FROM classes WHERE id=@id FOR UPDATE",c,t)){classLock.Parameters.AddWithValue("id",cl);await classLock.ExecuteScalarAsync();}await using var q=new NpgsqlCommand("SELECT status,expires_at,student_id FROM holds WHERE id=@id FOR UPDATE",c,t);q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync())return (IResult)Results.NotFound(new{message="The request could not be completed. Check your details and try again."});var state=r.GetString(0);var exp=r.GetDateTime(1);var owner=r.GetString(2);await r.CloseAsync();if(owner!=s)return (IResult)Results.StatusCode(403);if(state=="CONFIRMED")return (IResult)Results.Ok(new{holdId=id,status=state});if(state!="HELD"||exp<=DateTime.UtcNow)return (IResult)Results.Conflict(new{message="The request could not be completed. Check your details and try again."});await using(var u=new NpgsqlCommand("UPDATE holds SET status='CONFIRMED' WHERE id=@id",c,t)){u.Parameters.AddWithValue("id",id);await u.ExecuteNonQueryAsync();}await t.CommitAsync();return (IResult)Results.Ok(new{holdId=id,status="CONFIRMED"});});
app.MapDelete("/holds/{id}",async(string id,HttpRequest req)=>{var s=Student(req);if(s is null)return (IResult)Results.BadRequest(new{message="The request could not be completed. Check your details and try again."});await using var c=db.CreateCommand("UPDATE holds SET status='CANCELLED' WHERE id=@id AND student_id=@s AND status='HELD' AND expires_at>now() RETURNING id");c.Parameters.AddWithValue("id",id);c.Parameters.AddWithValue("s",s);if(await c.ExecuteScalarAsync() is null)return (IResult)Results.Conflict(new{message="The request could not be completed. Check your details and try again."});return (IResult)Results.NoContent();});
app.MapGet("/me/holds",async(HttpRequest req)=>{var s=Student(req);if(s is null)return (IResult)Results.BadRequest(new{message="The request could not be completed. Check your details and try again."});await using var c=db.CreateCommand("SELECT h.id,h.class_id,c.name,CASE WHEN h.status='HELD' AND h.expires_at<=now() THEN 'EXPIRED' ELSE h.status END,h.expires_at FROM holds h JOIN classes c ON c.id=h.class_id WHERE h.student_id=@s ORDER BY h.created_at DESC");c.Parameters.AddWithValue("s",s);await using var r=await c.ExecuteReaderAsync();var a=new List<object>();while(await r.ReadAsync())a.Add(new{holdId=r.GetString(0),classId=r.GetString(1),className=r.GetString(2),status=r.GetString(3),expiresAt=DateTime.SpecifyKind(r.GetDateTime(4),DateTimeKind.Utc)});return (IResult)Results.Ok(a);});app.Run();
static string? Student(HttpRequest r){var s=r.Headers["X-Student-Id"].ToString();return System.Text.RegularExpressions.Regex.IsMatch(s,@"^\d{17}$")?s:null;}
static async Task<List<object>> Classes(NpgsqlDataSource db,string? id){var sql="SELECT c.id,c.name,c.total_seats,count(*) FILTER(WHERE h.status='HELD' AND h.expires_at>now())::int,count(*) FILTER(WHERE h.status='CONFIRMED')::int FROM classes c LEFT JOIN holds h ON h.class_id=c.id"+(id==null?"":" WHERE c.id=@id")+" GROUP BY c.id ORDER BY c.created_at";await using var q=db.CreateCommand(sql);if(id!=null)q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync();var a=new List<object>();while(await r.ReadAsync()){var total=r.GetInt32(2);var held=r.GetInt32(3);var confirmed=r.GetInt32(4);a.Add(new{id=r.GetString(0),name=r.GetString(1),totalSeats=total,heldSeats=held,confirmedSeats=confirmed,availableSeats=total-held-confirmed});}return a;}
static async Task Init(NpgsqlDataSource db){await using var c=db.CreateCommand("CREATE TABLE IF NOT EXISTS classes(id text PRIMARY KEY,name varchar(120) NOT NULL,total_seats integer NOT NULL CHECK(total_seats>0),created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS holds(id text PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),student_id char(17) NOT NULL CHECK(student_id ~ '^[0-9]{17}$'),status text NOT NULL CHECK(status IN('HELD','CONFIRMED','EXPIRED','CANCELLED')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS ix_holds_class_state ON holds(class_id,status,expires_at);CREATE INDEX IF NOT EXISTS ix_holds_student_class ON holds(student_id,class_id,status);");await c.ExecuteNonQueryAsync();}
record CreateClass(string Name,int TotalSeats);public partial class Program{}
sealed class ExpiryWorker(NpgsqlDataSource db):BackgroundService{protected override async Task ExecuteAsync(CancellationToken token){while(!token.IsCancellationRequested){try{await using var c=db.CreateCommand("UPDATE holds SET status='EXPIRED' WHERE status='HELD' AND expires_at<=now()");await c.ExecuteNonQueryAsync();}catch{}await Task.Delay(2000,token);}}}



